import sys
import os
import json

def load_cache(cache_file):
    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache_file, cache):
    with open(cache_file, 'w') as f:
        json.dump(cache, f)

def evaluate_expression(expr, cache):
    if expr in cache:
        return cache[expr]
    try:
        value = eval(expr)
        cache[expr] = value
        return value
    except Exception as e:
        print(f'Error evaluating expression {expr}: {e}')
        return None

def main():
    if len(sys.argv) != 2:
        print('Usage: python calc_cache.py <cache_file>')
        return
    cache_file = sys.argv[1]
    cache = load_cache(cache_file)

    for line in sys.stdin:
        expr = line.strip()
        if expr:
            value = evaluate_expression(expr, cache)
            if value is not None:
                print(f'{expr} = {value}')

    save_cache(cache_file, cache)

if __name__ == '__main__':
    main()
